import {collectionTotals,cardsInSet,selectedAlbumSet,cardsForAlbumList} from './player-album-model.mjs';
export function createAlbumPage(options={}){
const $=id=>document.getElementById(id),root=new URL('./album-data/',import.meta.url),el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
let data,player,selected=0,filter='all',listKind=null,detailCard=null;const inventory=new Map(),pending=new Set();const owner=!!options.owner;
const nameOf=set=>set.name.replace(/ Set$/,'');
function trackerLinks(){if(owner)return;for(const id of ['open-tracker','detail-tracker']){const url=new URL('./my-album.html',import.meta.url);if(selected)url.searchParams.set('set',selected);$(id).href=url.href}}
function showSet(set){if(!Number.isInteger(set)||set<1||set>data.sets.length)return;selected=set;filter='all';render();if(!$('album-detail').open)$('album-detail').showModal();$('album-detail').querySelector('.modal-body').scrollTop=0}
function openCard(card){detailCard=card;const q=inventory.get(card.number)||0;$('card-title').textContent='#'+card.number+' · '+card.name;$('card-detail-art').src=new URL(card.image,root);$('card-detail-art').alt=card.name;$('card-description').textContent=card.stars+' stars'+(card.gold?' · Gold card':'')+' · '+(q?'Owned: '+q:'Missing');$('card-availability').textContent=q>1?(q-1)+' extra '+(q===2?'copy':'copies')+'. Trade eligibility depends on the player’s preferences and current game rules.':q===1?'This player has one copy.':'This player has not collected this card.';if(owner)$('owner-card-controls')?.replaceChildren(quantityControls(card));if(!$('card-dialog').open)$('card-dialog').showModal()}
function createCard(card){const q=inventory.get(card.number)||0,b=el('button',undefined,'public-card'+(q?'':' missing')+(card.gold?' gold':'')),image=el('img'),stars=el('img');b.type='button';b.dataset.card=card.number;b.setAttribute('aria-label','#'+card.number+' '+card.name+', '+card.stars+' stars, '+(q?'owned '+q:'missing'));image.src=new URL(card.image,root);image.alt='';image.className='card-art';image.loading='lazy';image.width=582;image.height=834;stars.src=new URL('./tatari-data/stars/'+String(card.stars).padStart(2,'0')+'.png',import.meta.url);stars.alt='';stars.className='card-stars';b.append(image,stars,el('span','No. '+card.number,'card-name'),el('span',q>1?'×'+q:q?'Owned':'Missing','card-state'+(q>1?' duplicate':'')));b.onclick=()=>openCard(card);if(!owner)return b;const tile=el('article',undefined,'owned-card-tile');tile.append(b,quantityControls(card));return tile}
function openAlbumList(kind){listKind=kind;
 const cards=cardsForAlbumList(data.cards,inventory,kind),titles={'lf':'LF Card','lf-gold':'LF Gold Card','ft':'FT Card'},descriptions={'lf':'Missing non-gold cards','lf-gold':'Missing gold cards','ft':'Duplicate cards'};
 $('album-list-title').textContent=titles[kind];$('album-list-description').textContent=descriptions[kind]+' · '+cards.length+' '+(cards.length===1?'card':'cards')+(kind==='ft'?' · '+collectionTotals(cards,inventory).extras+' extra copies':'');
 $('album-list-cards').replaceChildren(...cards.map(createCard));$('album-list-empty').hidden=cards.length>0;$('album-list-empty').textContent=kind==='ft'?'This player has no duplicate cards.':'This player has collected every '+(kind==='lf-gold'?'gold':'non-gold')+' card.';if(!$('album-list-dialog').open)$('album-list-dialog').showModal();
}
function render(){const totals=collectionTotals(data.cards,inventory);$('album-progress').textContent=String(cardsForAlbumList(data.cards,inventory,'lf').length);$('gold-progress').textContent=String(cardsForAlbumList(data.cards,inventory,'lf-gold').length);$('banner-progress-label').textContent=totals.collected+' / '+data.cards.length;$('duplicate-progress').textContent=totals.extras;$('collection-progress').value=totals.collected;$('collection-progress').max=data.cards.length;$('album-overview').hidden=false;trackerLinks();
 if(!$('album-set-grid').childElementCount)$('album-set-grid').replaceChildren(...data.sets.map(set=>{const count=set.cards.filter(n=>(inventory.get(n)||0)>0).length,b=el('button',undefined,'public-set'+(count===set.cards.length?' complete':'')),art=el('img'),progress=el('progress');b.type='button';b.setAttribute('aria-label',set.name+', '+count+' of '+set.cards.length+' collected');art.src=new URL(set.image,root);art.alt='';art.loading='lazy';art.width=220;art.height=220;progress.value=count;progress.max=set.cards.length;progress.setAttribute('aria-label',set.name+' progress');const chip=el('span',undefined,'set-progress-chip');progress.setAttribute('aria-label',set.name+' progress');chip.append(progress,el('span',count+' / '+set.cards.length,'set-counter'));const meta=el('span',undefined,'set-meta');meta.append(el('strong',nameOf(set)+' Set'),chip);b.append(art,meta);b.onclick=()=>showSet(set.number,{focus:true});return b}));
 if(!selected)return;const set=data.sets.find(s=>s.number===selected),count=set.cards.filter(n=>(inventory.get(n)||0)>0).length;$('set-title').textContent=set.name;$('set-image').src=new URL(set.image,root);$('set-progress').max=set.cards.length;$('set-progress').value=count;$('set-collected').textContent=count+' / '+set.cards.length;$('set-position').textContent=selected+' / '+data.sets.length;$('previous-set').disabled=selected===1;$('next-set').disabled=selected===data.sets.length;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)));
 const cards=cardsInSet(data.cards,selected,filter,inventory);$('cards-empty').hidden=!!cards.length;$('album-sets').replaceChildren(...cards.map(card=>{return createCard(card)}));
}
document.querySelectorAll('[data-album-list]').forEach(button=>button.onclick=()=>openAlbumList(button.dataset.albumList));$('close-album-list').onclick=()=>$('album-list-dialog').close();
if($('copy-player-uid'))$('copy-player-uid').onclick=async()=>{const b=$('copy-player-uid');try{await navigator.clipboard.writeText(String(player.uid));b.textContent='UID copied'}catch{b.textContent='Copy failed — try again'}};
$('close-set').onclick=()=>$('album-detail').close();$('album-detail').addEventListener('close',()=>{selected=0;filter='all';trackerLinks();const url=new URL(location.href);if(url.searchParams.has('set')){url.searchParams.delete('set');history.replaceState(null,'',url)}});$('previous-set').onclick=()=>showSet(selected-1,{focus:true});$('next-set').onclick=()=>showSet(selected+1,{focus:true});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render()});$('close-card').onclick=()=>$('card-dialog').close();

function quantityControls(card){const controls=el('div',undefined,'owner-quantity-controls'),q=inventory.get(card.number)||0;for(const delta of [-1,1]){const button=el('button',delta<0?'−':'+','btn secondary');button.type='button';button.dataset.quantityCard=card.number;button.dataset.delta=delta;button.setAttribute('aria-label',(delta>0?'Add':'Remove')+' card '+card.number);button.disabled=pending.has(card.number)||(delta<0?q===0:q>=999);button.onclick=()=>options.onAdjust?.(card,delta);controls.append(button);if(delta<0)controls.append(el('span',String(q),'owner-quantity'))}return controls}
return {
 setCollection(catalog,person,quantities,{initial=false}={}){data=catalog;player=person;inventory.clear();for(const [number,quantity] of quantities)inventory.set(number,quantity);if(initial)selected=selectedAlbumSet(location.href,data.sets.length);$('album-set-grid').replaceChildren();$('player-uid').textContent=player.uid?'UID '+player.uid:'';if($('copy-player-uid')){$('copy-player-uid').disabled=!player.uid;$('copy-player-uid').title=player.uid?'Copy UID '+player.uid:'Player UID is unavailable'}$('public-content').hidden=false;render();if(listKind&&$('album-list-dialog').open)openAlbumList(listKind);if(detailCard&&$('card-dialog').open)openCard(detailCard);if(initial&&selected&&!$('album-detail').open)$('album-detail').showModal()},
 setPending(number,busy){if(busy)pending.add(number);else pending.delete(number);document.querySelectorAll('[data-quantity-card="'+number+'"]').forEach(button=>{const q=inventory.get(number)||0,delta=Number(button.dataset.delta);button.disabled=busy||(delta<0?q===0:q>=999)})},
 status(text){$('album-status').textContent=text},
 clear(){for(const id of ['card-dialog','album-list-dialog','album-detail'])if($(id).open)$(id).close();$('public-content').hidden=true;$('album-set-grid').replaceChildren();inventory.clear();pending.clear()},
 selectedSet(){return selected||1}
};
}
